  ) o(maker, name, capacity_ml, outline)
  JOIN public.profiles p ON p.kind = 'maker' AND p.handle = o.maker
 WHERE m.maker_profile_id = p.id
   AND public.ingredient_key(m.name) = public.ingredient_key(o.name)
